/* ============================================================
   AgendaBot :: Helpers comunes (sin dependencias externas)
   Zona horaria fija: America/Bogota (UTC-5, sin horario de verano)
   ============================================================ */
const TZ_OFFSET_MS = -5 * 60 * 60 * 1000;
function pad(n, l) { return String(n).padStart(l, '0'); }
function ahora() { return new Date(Date.now() + TZ_OFFSET_MS); }
function aFechaISO(d) { return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1, 2) + '-' + pad(d.getUTCDate(), 2); }
function aHoraHM(d) { return pad(d.getUTCHours(), 2) + ':' + pad(d.getUTCMinutes(), 2); }
function hoyISO() { return aFechaISO(ahora()); }
function horaActual() { return aHoraHM(ahora()); }
function timestampCO() { const d = ahora(); return aFechaISO(d) + ' ' + aHoraHM(d) + ':' + pad(d.getUTCSeconds(), 2); }
function sumarDias(f, n) {
  const p = String(f).split('-').map(Number);
  return aFechaISO(new Date(Date.UTC(p[0], p[1] - 1, p[2] + n)));
}
function esFechaValida(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const p = String(s).split('-').map(Number);
  if (p[1] < 1 || p[1] > 12) return false;
  const diasMes = new Date(Date.UTC(p[0], p[1], 0)).getUTCDate();
  return p[2] >= 1 && p[2] <= diasMes && p[0] >= 2000 && p[0] <= 2100;
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s || '')); }
function esPasado(f, h) {
  const hoy = hoyISO();
  if (f < hoy) return true;
  if (f === hoy && h && h <= horaActual()) return true;
  return false;
}
function vacio(s) { return String(s == null ? '' : s).trim().length === 0; }
function limpiar(s) { return String(s == null ? '' : s).trim().replace(/\s+/g, ' ').slice(0, 200); }
function filasReales(items, clave) {
  return items.map(function (i) { return i.json; })
              .filter(function (r) { return r && r[clave] != null && String(r[clave]).trim() !== ''; });
}
function siguienteId(filas, campo, prefijo) {
  let max = 0;
  for (const r of filas) {
    const m = String(r[campo] || '').match(/(\d+)\s*$/);
    if (m) { const n = parseInt(m[1], 10); if (n > max) max = n; }
  }
  return prefijo + '-' + pad(max + 1, 3);
}
function leerDatos(t) { try { const o = JSON.parse(t || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
function esVerdadero(v) {
  const s = String(v == null ? '' : v).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === 'SI' || s === 'SÍ' || s === '1' || s === 'X' || s === 'YES';
}
const PIE = '\n————————\n9 Volver   ·   /menu Menú principal   ·   /cancelar Cancelar';
function opcionInvalida(extra) {
  return '⚠️ No entendí esa opción.\n' + (extra || 'Escribe únicamente el número de una de las opciones mostradas.');
}
function salida(mensaje, pantalla, paso, datos, resultado, accion, fila) {
  return [{ json: {
    mensaje: String(mensaje).slice(0, 3900),
    pantalla_nueva: pantalla,
    paso_nuevo: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    resultado: resultado || 'OK',
    accion: accion || 'NINGUNA',
    fila: fila || {}
  }}];
}

/* =====================================================================
   MODULO AGENDA
   Pantallas que atiende:
     AGENDA               menu del modulo
     AGENDA_NUEVA         wizard de 6 pasos (fecha, hora, nombre, motivo,
                          canal, resumen)
     AGENDA_REPROGRAMAR   pasos 1..3 (elegir cita, nueva fecha, nueva hora)
     AGENDA_CANCELAR      paso 1 (elegir cita)
     AGENDA_COMPLETAR     paso 1 (elegir cita)
   ===================================================================== */
const ctx = $('▶️ Entrada Agenda').first().json;
const filas = filasReales($input.all(), 'id_cita');

const texto = String(ctx.texto || '').trim();
const pantalla = String(ctx.pantalla_actual || 'AGENDA').toUpperCase();
const paso = String(ctx.paso_actual || '0');
const usuario = String(ctx.telegram_user);
const nombreUsuario = String(ctx.nombre || 'Usuario');
const d = leerDatos(ctx.datos_parciales);

const CANALES = { '1': 'Presencial', '2': 'Virtual', '3': 'Llamada' };
const ACTIVAS = ['PENDIENTE', 'REPROGRAMADA'];
const MANANA = sumarDias(hoyISO(), 1);

const MENU_AGENDA =
  '📅 AGENDA\n' +
  'Aquí gestionas tus citas: crearlas, consultarlas y cambiar su estado.\n\n' +
  '1  Agendar nueva cita\n' +
  '2  Consultar agenda\n' +
  '3  Reprogramar cita\n' +
  '4  Cancelar cita\n' +
  '5  Completar cita\n' +
  '9  Volver al menú principal\n\n' +
  '💡 Recomendado: 1 Agendar nueva cita\n' +
  'Tip: escribe únicamente el número.';

/* Entrada directa desde el menu principal: se muestra el menu del modulo
   sin consumir el numero que el usuario uso para entrar. */
if (ctx.entrada_modulo === true || String(ctx.entrada_modulo) === 'true')
  return salida(MENU_AGENDA, 'AGENDA', '0', {}, 'MENU_AGENDA');


function misCitas(estados) {
  return filas.filter(function (r) {
    return String(r.creado_por || '').trim() === usuario &&
           estados.indexOf(String(r.estado || '').trim().toUpperCase()) !== -1;
  }).sort(function (a, b) {
    return (String(a.fecha) + String(a.hora)).localeCompare(String(b.fecha) + String(b.hora));
  });
}

function listado(cs) {
  return cs.map(function (c, i) {
    return (i + 1) + ')  ' + c.fecha + '  ' + c.hora + '   ' + c.nombre +
           '\n      ' + c.motivo + '  ·  ' + c.canal + '  ·  ' + c.id_cita;
  }).join('\n');
}

function hayChoque(fecha, hora, excluirId) {
  return filas.some(function (r) {
    return String(r.creado_por || '').trim() === usuario &&
           String(r.fecha || '').trim() === fecha &&
           String(r.hora || '').trim() === hora &&
           ACTIVAS.indexOf(String(r.estado || '').trim().toUpperCase()) !== -1 &&
           String(r.id_cita || '') !== String(excluirId || '');
  });
}

function filaCompleta(c, cambios) {
  return {
    id_cita: c.id_cita,
    fecha: (cambios && cambios.fecha) || c.fecha,
    hora: (cambios && cambios.hora) || c.hora,
    nombre: c.nombre,
    motivo: c.motivo,
    canal: c.canal,
    estado: (cambios && cambios.estado) || c.estado,
    creado_por: c.creado_por,
    timestamp_creacion: c.timestamp_creacion
  };
}

function resumenBorrador() {
  return '📋 RESUMEN DE LA CITA\n\n' +
         '📅 Fecha:   ' + d.fecha + '\n' +
         '⏰ Hora:    ' + d.hora + '\n' +
         '👤 Nombre:  ' + d.nombre + '\n' +
         '📝 Motivo:  ' + d.motivo + '\n' +
         '📡 Canal:   ' + d.canal + '\n\n' +
         'Revisa que todo esté correcto.\n\n' +
         '1  Confirmar y guardar\n' +
         '2  Editar desde el principio\n' +
         '3  Cancelar la cita\n\n' +
         '💡 Recomendado: 1 Confirmar y guardar';
}

const P1 = '🆕 NUEVA CITA — Paso 1 de 6: FECHA\n\n' +
           '¿Para qué día quieres la cita?\n' +
           'Escríbela en formato AAAA-MM-DD.\n\n' +
           'Ejemplo: ' + MANANA + '\n\n' +
           '💡 Recomendado: ' + MANANA + ' (mañana)\n' +
           '9 Volver   ·   /cancelar Cancelar';
function P2() {
  return '🆕 NUEVA CITA — Paso 2 de 6: HORA\n\n' +
         '📅 Fecha elegida: ' + (d.fecha || '(sin fecha)') + '\n\n' +
         '¿A qué hora será la cita?\n' +
         'Escríbela en formato HH:MM de 24 horas.\n\n' +
         'Ejemplo: 15:30\n\n' +
         '💡 Recomendado: 09:00\n' +
         '9 Volver   ·   /cancelar Cancelar';
}
const P3 = '🆕 NUEVA CITA — Paso 3 de 6: NOMBRE\n\n' +
           '¿Con quién es la cita?\n' +
           'Escribe el nombre de la persona o de la empresa.\n\n' +
           'Ejemplo: María Gómez\n\n' +
           '9 Volver   ·   /cancelar Cancelar';
const P4 = '🆕 NUEVA CITA — Paso 4 de 6: MOTIVO\n\n' +
           '¿De qué se trata la cita?\n' +
           'Descríbelo en pocas palabras.\n\n' +
           'Ejemplo: Revisión del contrato de arrendamiento\n\n' +
           '9 Volver   ·   /cancelar Cancelar';
const P5 = '🆕 NUEVA CITA — Paso 5 de 6: CANAL\n\n' +
           '¿Cómo se hará la cita?\n\n' +
           '1  Presencial\n' +
           '2  Virtual\n' +
           '3  Llamada\n\n' +
           '💡 Recomendado: 1 Presencial\n' +
           '9 Volver   ·   /cancelar Cancelar';

/* ------------------------------------------------------- MENU DEL MODULO */
if (pantalla === 'AGENDA') {
  if (texto === '1') {
    return salida(P1, 'AGENDA_NUEVA', '1', {}, 'WIZARD_INICIADO');
  }
  if (texto === '2') {
    const cs = misCitas(ACTIVAS);
    if (cs.length === 0) {
      return salida('📭 No tienes citas activas por ahora.\n\n' +
                    'Cuando agendes una, aparecerá aquí.\n\n' + MENU_AGENDA,
                    'AGENDA', '0', {}, 'CONSULTA_VACIA');
    }
    return salida('📆 TUS PRÓXIMAS CITAS (' + cs.length + ')\n\n' +
                  listado(cs.slice(0, 15)) +
                  (cs.length > 15 ? '\n\n… y ' + (cs.length - 15) + ' más.' : '') +
                  '\n\n' + MENU_AGENDA,
                  'AGENDA', '0', {}, 'CONSULTA_OK');
  }
  if (texto === '3' || texto === '4' || texto === '5') {
    const cs = misCitas(texto === '5' ? ACTIVAS : ACTIVAS);
    const acciones = { '3': ['AGENDA_REPROGRAMAR', 'reprogramar'],
                       '4': ['AGENDA_CANCELAR', 'cancelar'],
                       '5': ['AGENDA_COMPLETAR', 'marcar como completada'] };
    const a = acciones[texto];
    if (cs.length === 0) {
      return salida('📭 No tienes citas activas que puedas ' + a[1] + '.\n\n' + MENU_AGENDA,
                    'AGENDA', '0', {}, 'SIN_CITAS');
    }
    const nd = { opciones: cs.map(function (c) { return c.id_cita; }) };
    return salida('🔧 ¿Cuál cita quieres ' + a[1] + '?\n\n' +
                  listado(cs) + '\n\n' +
                  'Escribe el número de la cita (1 a ' + cs.length + ').\n\n' +
                  '💡 Recomendado: 1 (la más próxima)\n' +
                  '9 Volver   ·   /cancelar Cancelar',
                  a[0], '1', nd, 'SELECCION_PEDIDA');
  }
  if (texto === '9') {
    return salida('👌 Volvamos al menú principal.\n\nEscribe /menu para verlo de nuevo.',
                  'MENU', '0', {}, 'VOLVER');
  }
  return salida(opcionInvalida('En Agenda espero un número del 1 al 5, o 9 para volver.') +
                '\n\n' + MENU_AGENDA, 'AGENDA', '0', {}, 'OPCION_INVALIDA');
}

/* ---------------------------------------------------- WIZARD NUEVA CITA */
if (pantalla === 'AGENDA_NUEVA') {

  if (paso === '1') {
    if (texto === '9') return salida(MENU_AGENDA, 'AGENDA', '0', {}, 'VOLVER');
    if (vacio(texto)) return salida('⚠️ La fecha no puede quedar vacía.\n\n' + P1,
                                    'AGENDA_NUEVA', '1', d, 'VACIO');
    if (!esFechaValida(texto))
      return salida('⚠️ Esa fecha no tiene el formato correcto.\n' +
                    'Debe ser AAAA-MM-DD, por ejemplo ' + MANANA + '.\n\n' + P1,
                    'AGENDA_NUEVA', '1', d, 'FECHA_INVALIDA');
    if (texto < hoyISO())
      return salida('⚠️ No puedo agendar citas en el pasado.\n' +
                    'Hoy es ' + hoyISO() + '. Elige esa fecha o una posterior.\n\n' + P1,
                    'AGENDA_NUEVA', '1', d, 'FECHA_PASADA');
    d.fecha = texto;
    return salida('✅ Fecha registrada: ' + d.fecha + '\n\n' + P2(),
                  'AGENDA_NUEVA', '2', d, 'PASO_1_OK');
  }

  if (paso === '2') {
    if (texto === '9') return salida(P1, 'AGENDA_NUEVA', '1', d, 'VOLVER_PASO');
    if (vacio(texto)) return salida('⚠️ La hora no puede quedar vacía.\n\n' + P2(),
                                    'AGENDA_NUEVA', '2', d, 'VACIO');
    if (!esHoraValida(texto))
      return salida('⚠️ Esa hora no tiene el formato correcto.\n' +
                    'Debe ser HH:MM en formato de 24 horas, por ejemplo 15:30.\n\n' + P2(),
                    'AGENDA_NUEVA', '2', d, 'HORA_INVALIDA');
    if (esPasado(d.fecha, texto))
      return salida('⚠️ Esa hora ya pasó.\n' +
                    'Ahora son las ' + horaActual() + ' del ' + hoyISO() + '.\n' +
                    'Elige una hora posterior.\n\n' + P2(),
                    'AGENDA_NUEVA', '2', d, 'HORA_PASADA');
    if (hayChoque(d.fecha, texto))
      return salida('⛔ Ya tienes una cita activa el ' + d.fecha + ' a las ' + texto + '.\n' +
                    'No puedo reservar dos citas a la misma hora.\n' +
                    'Elige otra hora, o vuelve con 9 y cancela la cita anterior.\n\n' + P2(),
                    'AGENDA_NUEVA', '2', d, 'DOBLE_RESERVA');
    d.hora = texto;
    return salida('✅ Hora registrada: ' + d.hora + '\n\n' + P3,
                  'AGENDA_NUEVA', '3', d, 'PASO_2_OK');
  }

  if (paso === '3') {
    if (texto === '9') return salida(P2(), 'AGENDA_NUEVA', '2', d, 'VOLVER_PASO');
    const n = limpiar(texto);
    if (vacio(n)) return salida('⚠️ El nombre no puede quedar vacío.\n\n' + P3,
                                'AGENDA_NUEVA', '3', d, 'VACIO');
    if (n.length < 2) return salida('⚠️ Ese nombre es demasiado corto.\n' +
                                    'Escribe al menos 2 caracteres.\n\n' + P3,
                                    'AGENDA_NUEVA', '3', d, 'NOMBRE_CORTO');
    d.nombre = n;
    return salida('✅ Nombre registrado: ' + d.nombre + '\n\n' + P4,
                  'AGENDA_NUEVA', '4', d, 'PASO_3_OK');
  }

  if (paso === '4') {
    if (texto === '9') return salida(P3, 'AGENDA_NUEVA', '3', d, 'VOLVER_PASO');
    const m = limpiar(texto);
    if (vacio(m)) return salida('⚠️ El motivo no puede quedar vacío.\n\n' + P4,
                                'AGENDA_NUEVA', '4', d, 'VACIO');
    if (m.length < 3) return salida('⚠️ Ese motivo es demasiado corto.\n' +
                                    'Descríbelo con al menos 3 caracteres.\n\n' + P4,
                                    'AGENDA_NUEVA', '4', d, 'MOTIVO_CORTO');
    d.motivo = m;
    return salida('✅ Motivo registrado: ' + d.motivo + '\n\n' + P5,
                  'AGENDA_NUEVA', '5', d, 'PASO_4_OK');
  }

  if (paso === '5') {
    if (texto === '9') return salida(P4, 'AGENDA_NUEVA', '4', d, 'VOLVER_PASO');
    const canal = CANALES[texto];
    if (!canal) return salida(opcionInvalida('Para el canal espero 1, 2 o 3.') + '\n\n' + P5,
                              'AGENDA_NUEVA', '5', d, 'CANAL_INVALIDO');
    d.canal = canal;
    return salida('✅ Canal registrado: ' + d.canal + '\n\n' + resumenBorrador(),
                  'AGENDA_NUEVA', '6', d, 'PASO_5_OK');
  }

  if (paso === '6') {
    if (texto === '2' || texto === '9')
      return salida('✏️ De acuerdo, empecemos de nuevo.\n\n' + P1,
                    'AGENDA_NUEVA', '1', {}, 'EDITAR');
    if (texto === '3')
      return salida('🗑️ Descarté la cita. No guardé nada.\n\n' + MENU_AGENDA,
                    'AGENDA', '0', {}, 'CANCELADO');
    if (texto !== '1')
      return salida(opcionInvalida('Aquí espero 1 (confirmar), 2 (editar) o 3 (cancelar).') +
                    '\n\n' + resumenBorrador(), 'AGENDA_NUEVA', '6', d, 'OPCION_INVALIDA');

    /* --- validacion final antes de escribir en Google Sheets --- */
    if (!d.fecha || !d.hora || !d.nombre || !d.motivo || !d.canal)
      return salida('⚠️ Faltan datos para guardar la cita.\n' +
                    'Vamos a repetir el proceso desde el principio.\n\n' + P1,
                    'AGENDA_NUEVA', '1', {}, 'DATOS_INCOMPLETOS');
    if (esPasado(d.fecha, d.hora))
      return salida('⚠️ Mientras completabas los datos, esa hora ya pasó.\n' +
                    'Elige una nueva fecha.\n\n' + P1,
                    'AGENDA_NUEVA', '1', {}, 'FECHA_PASADA');
    if (hayChoque(d.fecha, d.hora))
      return salida('⛔ Justo ahora ya existe otra cita activa el ' + d.fecha +
                    ' a las ' + d.hora + '.\nElige otra hora.\n\n' + P2(),
                    'AGENDA_NUEVA', '2', d, 'DOBLE_RESERVA');

    const nuevoId = siguienteId(filas, 'id_cita', 'CITA');
    const fila = {
      id_cita: nuevoId,
      fecha: d.fecha,
      hora: d.hora,
      nombre: d.nombre,
      motivo: d.motivo,
      canal: d.canal,
      estado: 'PENDIENTE',
      creado_por: usuario,
      timestamp_creacion: timestampCO()
    };
    const msg = '🎉 ¡Listo, ' + nombreUsuario + '! Tu cita quedó agendada.\n\n' +
                '🆔 Código:  ' + nuevoId + '\n' +
                '📅 Fecha:   ' + fila.fecha + '\n' +
                '⏰ Hora:    ' + fila.hora + '\n' +
                '👤 Nombre:  ' + fila.nombre + '\n' +
                '📝 Motivo:  ' + fila.motivo + '\n' +
                '📡 Canal:   ' + fila.canal + '\n' +
                '🔖 Estado:  PENDIENTE\n\n' +
                'Te avisaré cuando se acerque la hora.\n\n' + MENU_AGENDA;
    return salida(msg, 'AGENDA', '0', {}, 'CITA_CREADA:' + nuevoId, 'CREAR', fila);
  }

  return salida('🔄 Reinicio el asistente de citas para evitar confusiones.\n\n' + P1,
                'AGENDA_NUEVA', '1', {}, 'PASO_DESCONOCIDO');
}

/* ------------------------------------- REPROGRAMAR / CANCELAR / COMPLETAR */
if (pantalla === 'AGENDA_REPROGRAMAR' || pantalla === 'AGENDA_CANCELAR' || pantalla === 'AGENDA_COMPLETAR') {

  if (texto === '9' && paso === '1')
    return salida(MENU_AGENDA, 'AGENDA', '0', {}, 'VOLVER');

  const ids = Array.isArray(d.opciones) ? d.opciones : [];

  if (paso === '1') {
    const n = parseInt(texto, 10);
    if (!/^\d+$/.test(texto) || isNaN(n) || n < 1 || n > ids.length)
      return salida(opcionInvalida('Escribe un número entre 1 y ' + ids.length + '.'),
                    pantalla, '1', d, 'SELECCION_INVALIDA');

    const idSel = ids[n - 1];
    const cita = filas.find(function (r) { return String(r.id_cita) === String(idSel); });
    if (!cita)
      return salida('⚠️ No encontré esa cita. Es posible que haya cambiado.\n\n' + MENU_AGENDA,
                    'AGENDA', '0', {}, 'CITA_NO_ENCONTRADA');

    if (pantalla === 'AGENDA_CANCELAR') {
      const fila = filaCompleta(cita, { estado: 'CANCELADA' });
      return salida('🗑️ Cita cancelada correctamente.\n\n' +
                    '🆔 ' + cita.id_cita + '\n📅 ' + cita.fecha + '  ⏰ ' + cita.hora + '\n' +
                    '👤 ' + cita.nombre + '\n🔖 Estado: CANCELADA\n\n' +
                    'Esa franja horaria vuelve a quedar libre.\n\n' + MENU_AGENDA,
                    'AGENDA', '0', {}, 'CITA_CANCELADA:' + cita.id_cita, 'ACTUALIZAR', fila);
    }
    if (pantalla === 'AGENDA_COMPLETAR') {
      const fila = filaCompleta(cita, { estado: 'COMPLETADA' });
      return salida('✅ Cita marcada como completada. ¡Bien hecho!\n\n' +
                    '🆔 ' + cita.id_cita + '\n📅 ' + cita.fecha + '  ⏰ ' + cita.hora + '\n' +
                    '👤 ' + cita.nombre + '\n🔖 Estado: COMPLETADA\n\n' + MENU_AGENDA,
                    'AGENDA', '0', {}, 'CITA_COMPLETADA:' + cita.id_cita, 'ACTUALIZAR', fila);
    }
    d.id_cita = cita.id_cita;
    d.fecha_actual = cita.fecha;
    d.hora_actual = cita.hora;
    return salida('🔄 REPROGRAMAR — Paso 1 de 2: NUEVA FECHA\n\n' +
                  'Cita elegida: ' + cita.id_cita + ' · ' + cita.nombre + '\n' +
                  'Actualmente está para el ' + cita.fecha + ' a las ' + cita.hora + '.\n\n' +
                  '¿Para qué día la movemos?\n' +
                  'Formato AAAA-MM-DD. Ejemplo: ' + MANANA + '\n\n' +
                  '💡 Recomendado: ' + MANANA + '\n' +
                  '9 Volver   ·   /cancelar Cancelar',
                  'AGENDA_REPROGRAMAR', '2', d, 'REPROGRAMAR_FECHA');
  }

  if (pantalla === 'AGENDA_REPROGRAMAR' && paso === '2') {
    if (texto === '9') return salida(MENU_AGENDA, 'AGENDA', '0', {}, 'VOLVER');
    if (!esFechaValida(texto))
      return salida('⚠️ Formato de fecha incorrecto. Debe ser AAAA-MM-DD, ' +
                    'por ejemplo ' + MANANA + '.\n\nEscribe la nueva fecha:',
                    'AGENDA_REPROGRAMAR', '2', d, 'FECHA_INVALIDA');
    if (texto < hoyISO())
      return salida('⚠️ No puedo mover la cita al pasado. Hoy es ' + hoyISO() + '.\n\n' +
                    'Escribe la nueva fecha:', 'AGENDA_REPROGRAMAR', '2', d, 'FECHA_PASADA');
    d.nueva_fecha = texto;
    return salida('🔄 REPROGRAMAR — Paso 2 de 2: NUEVA HORA\n\n' +
                  'Nueva fecha: ' + d.nueva_fecha + '\n\n' +
                  '¿A qué hora? Formato HH:MM de 24 horas. Ejemplo: 15:30\n\n' +
                  '💡 Recomendado: ' + (d.hora_actual || '09:00') + ' (la misma de antes)\n' +
                  '9 Volver   ·   /cancelar Cancelar',
                  'AGENDA_REPROGRAMAR', '3', d, 'REPROGRAMAR_HORA');
  }

  if (pantalla === 'AGENDA_REPROGRAMAR' && paso === '3') {
    if (texto === '9') return salida(MENU_AGENDA, 'AGENDA', '0', {}, 'VOLVER');
    if (!esHoraValida(texto))
      return salida('⚠️ Formato de hora incorrecto. Debe ser HH:MM, por ejemplo 15:30.\n\n' +
                    'Escribe la nueva hora:', 'AGENDA_REPROGRAMAR', '3', d, 'HORA_INVALIDA');
    if (esPasado(d.nueva_fecha, texto))
      return salida('⚠️ Esa hora ya pasó. Ahora son las ' + horaActual() + '.\n\n' +
                    'Escribe la nueva hora:', 'AGENDA_REPROGRAMAR', '3', d, 'HORA_PASADA');
    if (hayChoque(d.nueva_fecha, texto, d.id_cita))
      return salida('⛔ Ya tienes otra cita activa el ' + d.nueva_fecha + ' a las ' + texto + '.\n\n' +
                    'Escribe otra hora:', 'AGENDA_REPROGRAMAR', '3', d, 'DOBLE_RESERVA');

    const cita = filas.find(function (r) { return String(r.id_cita) === String(d.id_cita); });
    if (!cita)
      return salida('⚠️ No encontré la cita original.\n\n' + MENU_AGENDA,
                    'AGENDA', '0', {}, 'CITA_NO_ENCONTRADA');

    const fila = filaCompleta(cita, { fecha: d.nueva_fecha, hora: texto, estado: 'REPROGRAMADA' });
    return salida('🔄 Cita reprogramada correctamente.\n\n' +
                  '🆔 ' + cita.id_cita + '\n' +
                  '👤 ' + cita.nombre + '\n' +
                  'Antes:   ' + cita.fecha + '  ' + cita.hora + '\n' +
                  'Ahora:   ' + fila.fecha + '  ' + fila.hora + '\n' +
                  '🔖 Estado: REPROGRAMADA\n\n' + MENU_AGENDA,
                  'AGENDA', '0', {}, 'CITA_REPROGRAMADA:' + cita.id_cita, 'ACTUALIZAR', fila);
  }

  return salida(MENU_AGENDA, 'AGENDA', '0', {}, 'PASO_DESCONOCIDO');
}

/* -------------------------------------------------------------- fallback */
return salida(MENU_AGENDA, 'AGENDA', '0', {}, 'PANTALLA_DESCONOCIDA');

